function validate([encoded1, encoded2]) {
  const totals = [];
  for (const [name, encoded] of [['encoded1', encoded1], ['encoded2', encoded2]]) {
    if (!Array.isArray(encoded) || encoded.length < 1 || encoded.length > 100000) return name + ' needs 1 to 10^5 pairs.';
    let total = 0;
    for (const pair of encoded) {
      if (!Array.isArray(pair) || pair.length !== 2) return 'Each entry of ' + name + ' is a [val, freq] pair.';
      if (!pair.every(x => Number.isInteger(x) && x >= 1 && x <= 10000)) return 'Every val and freq is between 1 and 10^4.';
      total += pair[1];
    }
    totals.push(total);
  }
  if (totals[0] !== totals[1]) return 'Both encodings must expand to the same length.';
  return null;
}

