    const [value1, freq1] = encoded1[i];
    const [value2, freq2] = encoded2[j];
    const count = Math.min(freq1 - used1, freq2 - used2);
    const product = value1 * value2;
    const last = result[result.length - 1];
    if (last !== undefined && last[0] === product) {
      last[1] += count;
    } else {
      result.push([product, count]);
    }
    used1 += count;
    used2 += count;
    if (used1 === freq1) {
      i++;
      used1 = 0;
    }
    if (used2 === freq2) {
      j++;
      used2 = 0;
    }
  }
  return result;
}

