function findRLEArray(encoded1, encoded2) {
  const expand = (encoded) => encoded.flatMap(([v, f]) => new Array(f).fill(v));
  const a = expand(encoded1);
  const b = expand(encoded2);
  const out = [];
  for (let k = 0; k < a.length; k++) {
    const p = a[k] * b[k];
    if (out.length > 0 && out[out.length - 1][0] === p) out[out.length - 1][1]++;
    else out.push([p, 1]);
  }
  return out;
}

