function generate(rand, size) {
  const large = size === 'large';
  const maxVal = large ? (rand() < 0.5 ? 3 : 10000) : 4;
  const maxFreq = large ? 10000 : 3;
  const pick = (m) => 1 + Math.floor(rand() * m);
  const nextValue = (encoded) => {
    const prev = encoded.length ? encoded[encoded.length - 1][0] : 0;
    for (;;) { const v = pick(maxVal); if (v !== prev) return v; }
  };
  const encoded1 = [];
  const segments = large ? 1200 : 1 + Math.floor(rand() * 5);
  let total = 0;
  for (let k = 0; k < segments; k++) {
    const f = pick(maxFreq);
    encoded1.push([nextValue(encoded1), f]);
    total += f;
  }
  const encoded2 = [];
  let remaining = total;
  while (remaining > 0) {
    const f = Math.min(remaining, pick(maxFreq));
    encoded2.push([nextValue(encoded2), f]);
    remaining -= f;
  }
  return rand() < 0.5 ? [encoded1, encoded2] : [encoded2, encoded1];
}
